// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _am, uint256 _lockTime, uint256 _dummy) public {
        // Restrict inputs to avoid reverts unrelated to the bug
        _val = bound(_val, 1, 1e18);
        _am = bound(_am, 0, 1e18);
        _lockTime = bound(_lockTime, 0, 1e12);
        uint256 initialMinSum = c.MinSum();

        // Scenario: call SetMinSum after initialization (in P this reverts, in M it succeeds)
        // First initialize (call Initialized)
        c.Initialized();
        // Now try to set MinSum; in P this reverts, in M it succeeds.
        (bool successSet, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val));

        // Call Collect with fuzz parameters
        c.Collect(_am);

        uint256 finalMinSum = c.MinSum();

        // Rule: If SetMinSum reverted (meaning it was called after init, in P), MinSum must be unchanged from initial.
        // In P, successSet is false => finalMinSum == initialMinSum.
        // In buggy M, successSet is true and MinSum is set to _val, so finalMinSum != initialMinSum (since _val > 0).
        assertTrue(!successSet || finalMinSum == initialMinSum);
    }
}

